Prikaži kod
w05_podaci = {
  const rng = d3.randomLcg(505);
  const normalna = () =&gt; {
    let x;
    let y;
    let radijus;
    do {
      x = rng() * 2 - 1;
      y = rng() * 2 - 1;
      radijus = x * x + y * y;
    } while (!radijus || radijus &gt; 1);
    return 0.85 * x * Math.sqrt(-2 * Math.log(radijus) / radijus);
  };

  return Array.from({length: 72}, (_, i) =&gt; {
    const skupina = i &lt; 36 ? "Skupina A" : "Skupina B";
    const x = 1 + (i % 36) * 9 / 35;
    const pomak = skupina === "Skupina B" ? 0.8 : 0;
    return {red: i + 1, skupina, x, y: 1.5 + 0.55 * x + pomak + normalna()};
  });
}









