  function erf(x) {
    const predznak = x &lt; 0 ? -1 : 1;
    const z = Math.abs(x);
    const t = 1 / (1 + 0.3275911 * z);
    const y = 1 - (((((1.061405429 * t - 1.453152027) * t) +
      1.421413741) * t - 0.284496736) * t + 0.254829592) *
      t * Math.exp(-z * z);
    return predznak * y;
  }

  const normalnaF = x =&gt; 0.5 * (1 + erf(x / Math.SQRT2));

  function normalnaBezSpremnika(source) {
    return () =&gt; {
      let x;
      let y;
      let radius;
      do {
        x = source() * 2 - 1;
        y = source() * 2 - 1;
        radius = x * x + y * y;
      } while (!radius || radius &gt; 1);
      return x * Math.sqrt(-2 * Math.log(radius) / radius);
    };
  }

  function kvantilNormalne(p) {
    let donja = -8;
    let gornja = 8;
    for (let i = 0; i &lt; 60; i += 1) {
