Prikaži kod
{
  const tinta = "var(--widget-ink)";
  const priguseno = "var(--tok-ink-mute)";
  const pravilo = "var(--widget-grid)";
  const povrsina = "var(--tok-surface)";
  const podatak = "var(--widget-fill)";
  const prilagodeno = "var(--widget-ink-secondary)";
  const naglasak = "var(--widget-emphasis)";
  const formatBroj = new Intl.NumberFormat("hr-HR", {
    maximumFractionDigits: 1
  });
  function normalnaBezSpremnika(source) {
    return () =&gt; {
      let x;
      let y;
      let radius;
      do {
        x = source() * 2 - 1;
        y = source() * 2 - 1;
        radius = x * x + y * y;
      } while (!radius || radius &gt; 1);
      return x * Math.sqrt(-2 * Math.log(radius) / radius);
    };
  }
  const rng = d3.randomLcg(1616);
  const normalna = normalnaBezSpremnika(rng);

  const podaci = Array.from({length: 52}, () =&gt; {
    const interes = normalna();
    const vrijeme = Math.max(0, 5 + 1.8 * interes + 1.5 * normalna());
    const angazman = 20 + 2.3 * vrijeme + 7 * interes + 4.5 * normalna();
    return {interes, vrijeme, angazman};
  });

  const regresija = (x, y) =&gt; {
    const mx = d3.mean(x);
    const my = d3.mean(y);
    const brojnik = d3.sum(x, (v, i) =&gt; (v - mx) * (y[i] - my));
    const nazivnik = d3.sum(x, v =&gt; (v - mx) ** 2);
    const b = brojnik / nazivnik;
    return {a: my - b * mx, b};
  };
  const x = podaci.map(d =&gt; d.vrijeme);
  const y = podaci.map(d =&gt; d.angazman);
  const z = podaci.map(d =&gt; d.interes);
  const zbirni = regresija(x, y);
  const xPremaZ = regresija(z, x);
  const yPremaZ = regresija(z, y);
  const xOstatak = x.map((v, i) =&gt; v - xPremaZ.a - xPremaZ.b * z[i]);
  const yOstatak = y.map((v, i) =&gt; v - yPremaZ.a - yPremaZ.b * z[i]);
  const prilagodeniNagib =
    d3.sum(xOstatak, (v, i) =&gt; v * yOstatak[i]) /
    d3.sum(xOstatak, v =&gt; v ** 2);
  const prilagodeni = {
    a: d3.mean(y) - prilagodeniNagib * d3.mean(x),
    b: prilagodeniNagib
  };

  const reziduali = podaci.map(d =&gt; ({
    ...d,
    procjena: w16_par.odsječak + w16_par.nagib * d.vrijeme
  }));
  const sse = d3.sum(reziduali, d =&gt;
    (d.angazman - d.procjena) ** 2);
  const sseNajmanji = d3.sum(podaci, d =&gt;
    (d.angazman - zbirni.a - zbirni.b * d.vrijeme) ** 2);
  const xRaspon = d3.extent(x);
  const xOdmak = (xRaspon[1] - xRaspon[0]) * 0.05;
  const xMin = Math.max(0, xRaspon[0] - xOdmak);
  const xMax = xRaspon[1] + xOdmak;
  const linija = model =&gt; [
    {x: xMin, y: model.a + model.b * xMin},
    {x: xMax, y: model.a + model.b * xMax}
  ];
  const korisnikov = {a: w16_par.odsječak, b: w16_par.nagib};
  const sveY = [
    ...y,
    ...linija(korisnikov).map(d =&gt; d.y),
    ...linija(zbirni).map(d =&gt; d.y),
    ...(w16_par.drugi ? linija(prilagodeni).map(d =&gt; d.y) : [])
  ];
  const yRaspon = d3.extent(sveY);
  const yOdmak = Math.max(3, (yRaspon[1] - yRaspon[0]) * 0.07);
  const celija =
    document.getElementById("fig-w16")?.closest(".cell") ??
    document.querySelector(".widget-frame .cell");
  const stilCelije = celija ? getComputedStyle(celija) : null;
  const lokalnaSirina = celija
    ? celija.clientWidth -
      (parseFloat(stilCelije.paddingLeft) || 0) -
      (parseFloat(stilCelije.paddingRight) || 0)
    : width;
  const sirinaGrafa = Math.max(
    1,
    Math.floor(Math.min(width, lokalnaSirina))
  );
  const mobilno = sirinaGrafa &lt; 480;
  const sazetakTekst =
    `Zbroj kvadrata ${formatBroj.format(sse)} · minimum ${formatBroj.format(sseNajmanji)}`;
  const graf = Plot.plot({
    width: sirinaGrafa,
    height: mobilno ? 410 : 365,
    marginTop: 20,
    marginRight: 20,
    marginBottom: mobilno ? 56 : 48,
    marginLeft: mobilno ? 62 : 58,
    style: {
      background: "transparent",
      color: tinta,
      fontFamily: "var(--tok-font-mono)",
      fontSize: mobilno ? "15px" : "13px"
    },
    x: {
      label: "Simulirano vrijeme",
      domain: [xMin, xMax],
      grid: true
    },
    y: {
      label: "Simulirani angažman",
      domain: [yRaspon[0] - yOdmak, yRaspon[1] + yOdmak],
      grid: true
    },
    marks: [
      Plot.ruleX(reziduali, {
        x: "vrijeme",
        y1: "angazman",
        y2: "procjena",
        stroke: naglasak,
        strokeOpacity: 0.35
      }),
      Plot.dot(podaci, {
        x: "vrijeme",
        y: "angazman",
        r: 4,
        fill: podatak,
        stroke: povrsina,
        strokeWidth: 0.8
      }),
      Plot.line(linija(korisnikov), {
        x: "x",
        y: "y",
        stroke: naglasak,
        strokeWidth: 2.8
      }),
      Plot.line(linija(zbirni), {
        x: "x",
        y: "y",
        stroke: tinta,
        strokeWidth: 1.8,
        strokeDasharray: "6,4"
      }),
      ...(w16_par.drugi ? [
        Plot.line(linija(prilagodeni), {
          x: "x",
          y: "y",
          stroke: prilagodeno,
          strokeWidth: 2,
          strokeDasharray: "2,3"
        })
      ] : []),
      Plot.text([{
        x: xMax,
        y: korisnikov.a + korisnikov.b * xMax,
        tekst: mobilno ? "pomični" : "pomični pravac"
      }], {
        x: "x",
        y: "y",
        text: "tekst",
        fill: naglasak,
        dy: -10,
        dx: -5,
        textAnchor: "end",
        fontWeight: 600
      }),
      Plot.text([{
        x: xMax,
        y: zbirni.a + zbirni.b * xMax,
        tekst: mobilno ? "najmanji" : "najmanji kvadrati"
      }], {
        x: "x",
        y: "y",
        text: "tekst",
        fill: tinta,
        dy: 11,
        dx: -5,
        textAnchor: "end",
        fontWeight: 600
      }),
      ...(w16_par.drugi ? [
        Plot.text([{
          x: xMax,
          y: prilagodeni.a + prilagodeni.b * xMax,
          tekst: mobilno ? "uz interes" : "uz jednak interes"
        }], {
          x: "x",
          y: "y",
          text: "tekst",
          fill: prilagodeno,
          dy: 22,
          dx: -5,
          textAnchor: "end",
          fontWeight: 600
        })
      ] : []),
      Plot.ruleY([yRaspon[0] - yOdmak], {stroke: pravilo})
    ]
  });
  return html`&lt;div&gt;
    ${graf}
    &lt;p class="widget-foot" role="status" aria-live="polite"&gt;${sazetakTekst}&lt;/p&gt;
  &lt;/div&gt;`;
}









Slika 4: Regresijski pravac — pomični pravac, reziduali i usporedba zbirnog s prilagođenim nagibom.





Što isprobati.

Mijenjajte odsječak i nagib dok se zbroj kvadrata ne približi prikazanom minimumu.
Povećajte samo nagib za jednu jedinicu i pratite koji se reziduali najviše produljuju.
Uključite model s prethodnim interesom i usporedite njegov nagib sa zbirnim pravcem.

Blizu minimuma manji pomaci pravca mogu samo malo povećati zbroj kvadrata. Kod uzorka je taj odnos dio računa nesigurnosti koeficijenata. Ovaj prikaz sam ne daje interval ni procjenu uzoračne nesigurnosti.
Prije nastavka vratite se glavnom primjeru s povjerenjem. Pokušajte bez ponovnog čitanja objasniti koju veličinu ondje računamo, što mjeri rezidual, kako biramo pravac i što bi bilo potrebno za uzročni zaključak.

Interakcija — Istraživač pravednosti
Za ovaj pokus zadajemo referentne ishode 0 i 1, ne ton stvarnih rečenica. Za ishod 0 generiramo 6.000 rezultata iz normalne raspodjele sa sredinom 0,30 i standardnom devijacijom 0,18, a za ishod 1 drugih 6.000 sa sredinom 0,70 i istom standardnom devijacijom. Vrijednosti ispod nule zamjenjujemo nulom, a iznad jedan jedinicom. Tako dobiveni brojevi služe razvrstavanju, bez pretpostavke da su kalibrirane vjerojatnosti. Kalibracija iz poglavlja o vjerojatnosti tražila bi slaganje najavljenih izgleda s učestalošću ishoda među usporedivim prognozama. Ovdje to nismo provjerili.
Pri pragu 0,60 rezultat 0,65 vodi pozitivnoj odluci. Ako je referentni ishod 0, taj zapis ulazi u brojnik lažno pozitivnih. Taj broj dijelimo sa svih 6.000 zapisa ishoda 0. Analogno među 6.000 zapisa ishoda 1 brojimo rezultate ispod praga za stopu lažno negativnih. Sve vrijednosti zadržavamo, uključujući one ograničene na nulu i jedan.
Skupine A i B zatim slažemo ponderiranjem istih dviju uvjetnih raspodjela, u prikazanoj postavci s udjelima ishoda 1 od 20 % i 45 %. Obje se skupine temelje na istim generiranim rezultatima, uz različite težine. Primjerice, u A udio točno pozitivnih među svima iznosi \(0,20(1-\text{stopa lažno negativnih})\), a udio lažno pozitivnih \(0,80 \times \text{stopa lažno pozitivnih}\). Njihov zbroj nazivnik je pozitivne prediktivne vrijednosti. U B mijenjaju se težine u 0,45 i 0,55. Uvjetne stope zato su u prikazu točno jednake po konstrukciji. Novi niz simuliranih rezultata malo bi promijenio njihove vrijednosti.
Na slici uspoređujemo dvije simulirane skupine s različitim temeljnim stopama. Za isti referentni ishod raspodjele rezultata jednake su u obje skupine. Zajednički prag zato može dati jednake uvjetne stope pogreške, ali različitu točnost i prediktivnu vrijednost. Zaključci prikaza odnose se na taj zaseban simulirani model.



